                            "pending",
                            "completed"
                        ],
                        "x-php-class": "TaskStatus"
                    }
                },
                "required": [
                    "title",
                    "description",
                    "dueDate",
                    "owner",
                    "status"
                ],
                "x-php-class": "\\Task",
                "additionalProperties": false
            }
        }
    },
    "required": [
        "meetingDate",
        "tasks"
    ],
    "x-php-class": "Tasks",
    "additionalProperties": false
}"},{"role":"user","content":"Transcription of meeting from 2024-01-15, 16:00
---
